// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime, uint256 timeShift) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 100 ether);
        timeShift = bound(timeShift, 1, 10_000 days);
        unlockTime = bound(unlockTime, 0, block.timestamp + 365 days);

        vm.warp(block.timestamp + timeShift);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        assertTrue(__invmut_c_Acc_unlockTime(actor) >= block.timestamp);
    }

    function __invmut_c_Acc_unlockTime(address __k) internal view returns (uint256) {
        (uint256 _v0, ) = c.Acc(__k);
        return _v0;
    }
}
